const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const requestTimeoutMs = Number($env.AUTOMATION_RUNNER_REQUEST_TIMEOUT_MS || 30000);
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
if (typeof globalThis.fetch !== 'function') {
  throw new Error('globalThis.fetch is not available in this n8n Code node environment');
}

const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const request = async (urlString, options = {}) => {
  const controller = new AbortController();
  const timeoutMs = Number(options.timeoutMs || requestTimeoutMs);
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await globalThis.fetch(urlString, {
      method: options.method || 'GET',
      headers: options.headers || {},
      body: options.body,
      signal: controller.signal,
    });
    const body = await response.text();
    return {
      statusCode: response.status || 0,
      body,
    };
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error(`Request timed out after ${timeoutMs}ms: ${urlString}`);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
};

const parseJson = (value, fallback, contextLabel) => {
  if (!value) {
    return fallback;
  }
  try {
    return JSON.parse(value);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Could not parse JSON from ${contextLabel}: ${message}`);
  }
};

const statusResponse = await request(`${runnerBase}/repo/status`, { headers });
if (statusResponse.statusCode < 200 || statusResponse.statusCode >= 300) {
  throw new Error(`Runner repo status failed: ${statusResponse.statusCode} ${statusResponse.body}`);
}
const repoStatus = parseJson(statusResponse.body, {}, 'repo/status');

let action = 'noop';
let mode = 'async';
let args = [];
let dedupeKey = 'open-pr-sweep';
let reason = 'Sweep skipped.';

if (repoStatus.branch !== 'main') {
  reason = `Repository is on ${repoStatus.branch}; open PR sweep only runs from main.`;
} else if (!repoStatus.clean) {
  reason = 'Working tree is not clean; refusing repo-wide PR sweep.';
} else {
  action = 'pr_sweep_open';
  reason = 'Repository is on clean main, so launch the repo-wide PR sweep.';
}

let jobResult = null;
if (action !== 'noop') {
  const jobResponse = await request(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action, mode, args, dedupeKey }),
  });
  if (![200, 202].includes(jobResponse.statusCode)) {
    throw new Error(`Runner job failed: ${jobResponse.statusCode} ${jobResponse.body}`);
  }
  jobResult = parseJson(jobResponse.body, null, 'jobs');
}

const timestamp = new Date().toISOString().replace(/[:]/g, '-');
const reportRelativePath = `github-pr-sweeps/${timestamp}-launcher.md`;
const reportContent = [
  '# GitHub Open PR Sweep Launcher',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Branch: ${repoStatus.branch}`,
  `Working tree clean: ${repoStatus.clean}`,
  '',
  `Action: ${action}`,
  reason,
  '',
  '## Job Result',
  '',
  jobResult ? '```json\n' + JSON.stringify(jobResult, null, 2) + '\n```' : 'No job was launched.',
].join('\n');

const writeResponse = await request(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (writeResponse.statusCode < 200 || writeResponse.statusCode >= 300) {
  throw new Error(`Runner report write failed: ${writeResponse.statusCode} ${writeResponse.body}`);
}

return [{ json: { generatedAt: new Date().toISOString(), action, reason, reportRelativePath, repoStatus, jobResult } }];
